def even_popcount_xor_triplets(a,b,c):
    def counts(values):
        odd=sum(value.bit_count()&1 for value in values);return len(values)-odd,odd
    ae,ao=counts(a);be,bo=counts(b);ce,co=counts(c)
    return ae*be*ce+ae*bo*co+ao*be*co+ao*bo*ce

